package com.example.payment.integrationtest.paymentgateway;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

import com.example.payment.domain.AuthorizationOutcome;
import com.example.payment.domain.Money;
import com.example.payment.infrastructure.HttpPaymentGateway;
import java.io.IOException;
import java.math.BigDecimal;
import mockwebserver3.MockResponse;
import mockwebserver3.MockWebServer;
import mockwebserver3.RecordedRequest;
import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.springframework.web.client.RestClient;

/**
 * Exercises {@link HttpPaymentGateway} against a real HTTP server double, proving that the
 * request we send and the responses we read back are wired up correctly, including the
 * provider's own way of refusing a payment.
 */
class HttpPaymentGatewayTest {

    private MockWebServer server;
    private HttpPaymentGateway gateway;

    @BeforeEach
    void startServer() throws IOException {
        server = new MockWebServer();
        server.start();
        var client = RestClient.builder().baseUrl(server.url("/").toString()).build();
        gateway = new HttpPaymentGateway(client);
    }

    @AfterEach
    void stopServer() throws IOException {
        server.close();
    }

    @Test
    void sends_the_reference_and_amount_as_json_to_the_authorizations_endpoint() throws Exception {
        server.enqueue(new MockResponse.Builder()
                .code(200)
                .body("{\"status\":\"approved\"}")
                .addHeader("Content-Type", "application/json")
                .build());

        gateway.authorize("ORD-7", new Money(new BigDecimal("12.50"), "eur"));

        RecordedRequest request = server.takeRequest();
        assertThat(request.getMethod()).isEqualTo("POST");
        assertThat(request.getUrl().encodedPath()).isEqualTo("/v1/authorizations");
        assertThat(request.getHeaders().get("Content-Type")).startsWith("application/json");
        assertThat(request.getBody().utf8()).isEqualTo("{\"reference\":\"ORD-7\",\"amount\":12.50,\"currency\":\"EUR\"}");
    }

    @Test
    void an_approved_response_is_read_back_as_approved() {
        server.enqueue(new MockResponse.Builder()
                .code(200)
                .body("{\"status\":\"approved\"}")
                .addHeader("Content-Type", "application/json")
                .build());

        var outcome = gateway.authorize("ORD-1", new Money(BigDecimal.TEN, "USD"));

        assertThat(outcome).isEqualTo(AuthorizationOutcome.APPROVED);
    }

    @Test
    void a_declined_response_is_read_back_as_declined() {
        server.enqueue(new MockResponse.Builder()
                .code(200)
                .body("{\"status\":\"declined\"}")
                .addHeader("Content-Type", "application/json")
                .build());

        var outcome = gateway.authorize("ORD-2", new Money(BigDecimal.TEN, "USD"));

        assertThat(outcome).isEqualTo(AuthorizationOutcome.DECLINED);
    }

    @Test
    void the_provider_refusing_the_payment_outright_with_402_is_read_back_as_declined() {
        server.enqueue(new MockResponse.Builder().code(402).build());

        var outcome = gateway.authorize("ORD-3", new Money(BigDecimal.TEN, "USD"));

        assertThat(outcome).isEqualTo(AuthorizationOutcome.DECLINED);
    }

    @Test
    void an_unexpected_status_value_in_the_body_is_treated_as_declined_rather_than_approved() {
        server.enqueue(new MockResponse.Builder()
                .code(200)
                .body("{\"status\":\"pending_review\"}")
                .addHeader("Content-Type", "application/json")
                .build());

        var outcome = gateway.authorize("ORD-4", new Money(BigDecimal.TEN, "USD"));

        assertThat(outcome).isEqualTo(AuthorizationOutcome.DECLINED);
    }

    @Test
    void an_empty_body_is_treated_as_declined_rather_than_approved() {
        server.enqueue(new MockResponse.Builder()
                .code(200)
                .addHeader("Content-Type", "application/json")
                .build());

        var outcome = gateway.authorize("ORD-5", new Money(BigDecimal.TEN, "USD"));

        assertThat(outcome).isEqualTo(AuthorizationOutcome.DECLINED);
    }

    @Test
    void a_server_error_from_the_provider_is_surfaced_as_a_failure_rather_than_silently_declined() {
        server.enqueue(new MockResponse.Builder().code(500).body("boom").build());

        assertThatThrownBy(() -> gateway.authorize("ORD-6", new Money(BigDecimal.TEN, "USD")))
                .isInstanceOf(IllegalStateException.class)
                .hasMessageContaining("500");
    }

    @Test
    void an_unauthorized_response_is_surfaced_as_a_failure_rather_than_silently_declined() {
        server.enqueue(new MockResponse.Builder().code(401).build());

        assertThatThrownBy(() -> gateway.authorize("ORD-8", new Money(BigDecimal.TEN, "USD")))
                .isInstanceOf(IllegalStateException.class)
                .hasMessageContaining("401");
    }
}

